/** Actual original daily → native weekly/monthly prepare/claim/send/apply.
 * Source/settings genesis and model transport are fictional; missing days remain explicit partial coverage. */
class ReportPeriodNativeGenerationTest {
 boolean mysql(){return false;}ReportNativeGenerationIntegrationTest daily;ReportPeriodInputComponentService periods;int sends;
 void setup()throws Exception{daily=new ReportNativeGenerationIntegrationTest(){@Override boolean mysql(){return ReportPeriodNativeGenerationTest.this.mysql();}};daily.setup();assertEquals(ResultApplicationService.Status.APPLIED,daily.apply().status());var base=daily.h.h.h.f.data.nativeData().fixture().f();var ready=daily.ready();var first=new VersionAvailabilityService(new FrozenContentVersionService(new JdbcFrozenContentVersions(base.source)),new JdbcVersionAvailability(base.source),base.writes,base.tx,Clock.fixed(daily.clock.instant().plusSeconds(1),ZoneOffset.UTC));ReportOriginalCompletionTest.utc(()->first.capture(ready.version()));periods=ReportPeriodInputProofConfiguration.assemble(base.source,base.tx,daily.clock,new ReportOriginalCompletionService(base.source,base.tx));}
 ReportPreparedInputService.Prepared prepare(Stage stage,LocalDate last){var base=daily.h.h.h.f.data.nativeData().fixture().f();var clock=Clock.fixed(last.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant().plusSeconds(1),ZoneOffset.UTC);var capture=new ReportInputCaptureService(daily.h.h.h.f.service,periods,base.tx);var admission=new ReportInputWriterAdmissionService(base.source,base.tx,capture);var members=new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(base.source));var metadata=new ReportPublicMetadataEnricher(new ArticlePublicEvidenceService(new JdbcArticlePublicEvidence(base.source),members),members,new FrozenContentVersionService(new JdbcFrozenContentVersions(base.source)));var originals=new ReportPreparedInputService(base.source,base.tx);var service=new ReportPreparationService(base.source,originals,admission,base.writes,()->new FrozenGenerationSettings(1,List.of(),List.of()),metadata,new GenerationRequestBuilder(),clock,()->true);return ReportOriginalCompletionTest.utc(()->service.prepare(new ReportInputCaptureService.Scope("report:"+(stage==Stage.WEEKLY_REPORT?"weekly":"monthly")+":"+last,1,stage,last)));}
 String raw(ResultApplicationService.Input input){var core=(ObjectNode)CanonicalJson.parse(daily.raw(input));((ObjectNode)core.get("payload").get("body")).put("type",input.stage()==Stage.WEEKLY_REPORT?"weekly":"monthly");core.remove("result_hash");try{var hash=MessageDigest.getInstance("SHA-256");hash.update("ai-result-v1\n".getBytes(StandardCharsets.UTF_8));hash.update(CanonicalJson.bytes(core));core.put("result_hash",HexFormat.of().formatHex(hash.digest()));return JdbcFrozenInputs.canonical(core);}catch(Exception impossible){throw new IllegalStateException(impossible);}}
 void sendAndApply(ReportPreparedInputService.Prepared prepared){var base=daily.h.h.h.f.data.nativeData().fixture().f();var clock=Clock.fixed(prepared.input().cutoff().plusSeconds(1),ZoneOffset.UTC);var worker=new WorkerAuthorizationService(base.writes,new WorkerJdbcStore(new JdbcWorkerState(base.source),new JdbcJobRecords(base.source),"fictional-period-worker",()->false,daily.h.readiness,clock,base.tx),clock,()->true);
  ReportOriginalCompletionTest.utc(()->{String root=prepared.input().ownerId();var claim=worker.claim(new SharedWriteExecutor.ActionContext("fictional-period-claim:"+prepared.scope().stage(),root,prepared.input().inputHash()));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(root,claim.permit().identity().rootId());var identity=claim.permit().identity();var complete=ReportPreparationInputProfile.complete(CanonicalJson.parse(prepared.input().snapshotJson()));var expected=complete.command().applicationContext().input(root,identity.attemptId(),identity.inputHash(),new JdbcJobRecords(base.source).byId(root).revision());String raw=raw(expected);assertEquals(WorkerAuthorizationService.State.SENT,worker.dispatch(claim.permit(),request->{assertEquals(identity.frozenRequestJson(),request);assertEquals(CanonicalJson.parse(prepared.input().requestJson()),CanonicalJson.parse(request));sends++;return raw;}).state());var graph=new SourceAnalysisProofGraph(base.source,base.tx,clock,()->false);var factory=new ResultApplicationFactory(base.source,base.tx,clock,graph.dependencies(),graph.dedupPermits(),fictionalUnusedCatalogs(),new JdbcEntityHeatSnapshots(base.source),daily.h.h.permits);var application=factory.forAttempt(identity);var action=new SharedWriteExecutor.ActionContext("fictional-period-result:"+prepared.scope().stage(),root,identity.inputHash());assertEquals(ResultApplicationService.Status.APPLIED,application.service().applyAutomatic(application.input(),raw,action).status());assertEquals(ResultApplicationService.Status.APPLIED,application.service().applyAutomatic(application.input(),raw,action).status());assertEquals("free",new JdbcWorkerState(base.source).slot().state());assertEquals(1,new JdbcJobRecords(base.source).byId(root).callCount());return true;});}
 Map<String,CatalogDayAnalysisResultPermitService> fictionalUnusedCatalogs(){var values=new HashMap<String,CatalogDayAnalysisResultPermitService>();for(String category:List.of("agent","skill","workflow","model"))values.put(category,org.mockito.Mockito.mock(CatalogDayAnalysisResultPermitService.class));return values;}
 @Test void ActualWeeklyAndMonthlyNativeInputsUseOriginalDailyBodyAndPreserveExplicitMissingDates()throws Exception{setup();var base=daily.h.h.h.f.data.nativeData().fixture().f();var day=daily.h.h.original.scope().day();String dailyBody=base.jdbc.queryForObject("SELECT body_json FROM contents WHERE input_job_id=?",String.class,daily.identity.rootId());var sunday=day.with(TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY));var month=day.withDayOfMonth(day.lengthOfMonth());for(var stage:List.of(Stage.WEEKLY_REPORT,Stage.MONTHLY_REPORT)){var prepared=prepare(stage,stage==Stage.WEEKLY_REPORT?sunday:month);assertEquals("queued",prepared.input().state());assertEquals("partial",prepared.input().coverageState());var snapshot=CanonicalJson.parse(prepared.input().snapshotJson());assertEquals(1,snapshot.get("members").size());assertEquals(CanonicalJson.parse(dailyBody),snapshot.get("members").get(0).get("body"));assertEquals(stage==Stage.WEEKLY_REPORT?6:month.lengthOfMonth()-1,snapshot.get(ReportInputProfile.FIELD).get("coverage").get("missing_dates").size());assertEquals(1,snapshot.get(FrozenPublicMetadata.FIELD).get("citations").size());sendAndApply(prepared);var content=base.jdbc.queryForObject("SELECT body_json FROM contents WHERE input_job_id=?",String.class,prepared.input().ownerId());assertEquals(stage==Stage.WEEKLY_REPORT?"weekly":"monthly",CanonicalJson.parse(content).get("type").asString());assertEquals(1L,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='report_result_ready' AND target_key_json LIKE ?",Long.class,"%"+prepared.input().ownerId()+"%"));assertEquals(prepared,new ReportPreparedInputService(base.source,base.tx).find(prepared.scope()));}assertEquals(2,sends);assertEquals(1,daily.reportSends);assertEquals(dailyBody,base.jdbc.queryForObject("SELECT body_json FROM contents WHERE input_job_id=?",String.class,daily.identity.rootId()));}
 @Test void DamagedOriginalDailyInputCannotCreateAnyPeriodBudgetEvenWhileCurrentBodyRemains()throws Exception{setup();var base=daily.h.h.h.f.data.nativeData().fixture().f();var day=daily.h.h.original.scope().day();int count=base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Integer.class);String body=base.jdbc.queryForObject("SELECT body_json FROM contents WHERE input_job_id=?",String.class,daily.identity.rootId());assertTrue(base.jdbc.update("UPDATE jobs SET payload_hash=? WHERE record_kind='snapshot_part' AND purpose='input' AND owner_job_id=?",new byte[32],daily.identity.rootId())>0);assertThrows(RuntimeException.class,()->prepare(Stage.WEEKLY_REPORT,day.with(TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY))));assertThrows(RuntimeException.class,()->prepare(Stage.MONTHLY_REPORT,day.withDayOfMonth(day.lengthOfMonth())));assertEquals(count,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Integer.class));assertEquals(body,base.jdbc.queryForObject("SELECT body_json FROM contents WHERE input_job_id=?",String.class,daily.identity.rootId()));assertEquals(0,sends);assertEquals(1,daily.reportSends);}
}
